import type { Metadata } from "next";
import { contact, routeInfo } from "./site";

// Share image generated by app/opengraph-image.tsx, repeated on every page
// (a page that sets its own openGraph does not inherit the root one).
const shareImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${contact.name} — ${contact.jobTitle}`,
};

/**
 * Builds a page's metadata from lib/site.ts: title, description, canonical URL,
 * and the Open Graph / Twitter tags used when the link is shared (LinkedIn, Slack, X…).
 */
export function pageMetadata(path: string, options: { noindex?: boolean } = {}): Metadata {
  const r = routeInfo(path);
  return {
    title: path === "/" ? { absolute: r.title } : r.title,
    description: r.description,
    alternates: { canonical: path },
    openGraph: { url: path, title: r.title, description: r.description, images: [shareImage] },
    twitter: { card: "summary_large_image", title: r.title, description: r.description, images: [shareImage.url] },
    ...(options.noindex && { robots: { index: false, follow: true } }),
  };
}
